import 'conversation.dart';
import 'conversation_store.dart';
import '../ai/memory/utils/async_lock.dart';
class InMemoryConversationStore implements ConversationStore { final Map<String, Conversation> _store = {}; final AsyncLock _lock = AsyncLock(); @override Future<Conversation> save(Conversation c) { return _lock.synchronized(() async { _store[c.id] = c; return c; }); } @override Future<Conversation?> getById(String id) { return _lock.synchronized(() async => _store[id]); } @override Future<List<Conversation>> getAll() { return _lock.synchronized(() async { final list = _store.values.toList(); list.sort((a, b) { if (a.pinned != b.pinned) return a.pinned ? -1 : 1; return b.lastMessageAt.compareTo(a.lastMessageAt); }); return list; }); } @override Future<void> delete(String id) { return _lock.synchronized(() async { _store.remove(id); }); } @override Future<void> clear() { return _lock.synchronized(() async { _store.clear(); }); } @override Future<int> count() { return _lock.synchronized(() async => _store.length); } }
